mapper.select:
SELECT u.id, IF((SELECT COUNT(1) FROM user_block b WHERE b.user_id = u.id AND b.block_id = #{userId}) > 0, NULL, u.email) AS email, NULL AS password, -- 如果对方将当前用户拉黑，则将相关字段设置为 NULL IF((SELECT COUNT(1) FROM user_block b WHERE b.user_id = u.id AND b.block_id = #{userId}) > 0, NULL, IF(fs_friend_to_user.get_username = 1, NULL, u.name)) AS name, IF((SELECT COUNT(1) FROM user_block b WHERE b.user_id = u.id AND b.block_id = #{userId}) > 0, NULL, IF(fs_friend_to_user.get_phone = 1, NULL, u.phone_num)) AS phone_num, u.nickname, u.avatar, -- 对方拉黑则将签名和活动图片设置为 NULL IF((SELECT COUNT(1) FROM user_block b WHERE b.user_id = u.id AND b.block_id = #{userId}) > 0, NULL, u.signature) AS signature, IF((SELECT COUNT(1) FROM user_block b WHERE b.user_id = u.id AND b.block_id = #{userId}) > 0, NULL, u.activity_img) AS activity_img, NULL AS settingsId, NULL AS createTime FROM user u JOIN friend_setting fs_user_to_friend ON u.id = fs_user_to_friend.friend_id JOIN friend_setting fs_friend_to_user ON fs_friend_to_user.user_id = u.id AND fs_friend_to_user.friend_id = #{userId} WHERE fs_user_to_friend.user_id = #{userId}
AND fs_user_to_friend.category_id = #{categoryId}
AND NOT EXISTS ( SELECT 1 FROM user_block b WHERE b.user_id = #{userId} AND b.block_id = u.id )
